export const SAMPLES: Record<string, string> = {
  "firmware/ee-pinching-stm32/can.h": "/* ============================================================\n * can.h — 적심 EE 보드 CAN HAL + watchdog 래퍼(골격).\n * ============================================================ */\n#ifndef STATION_EEP_CAN_H\n#define STATION_EEP_CAN_H\n#include <stdint.h>\n\ntypedef void (*can_rx_cb)(uint32_t id, const uint8_t *data, uint8_t len);\n\nvoid can_init(uint32_t bitrate);\nvoid can_send(uint32_t ext_id, const uint8_t *data, uint8_t len);\nvoid can_on_receive(can_rx_cb cb);\nvoid watchdog_start(uint32_t timeout_ms);\nvoid watchdog_refresh(void);\n\n#endif /* STATION_EEP_CAN_H */\n",
  "firmware/ee-pinching-stm32/ee.h": "/* ============================================================\n * ee.h — 적심(Pinching) 엔드이펙터 공용 정의. 벤더: GreenEdge (MOD-EE-PINCH, FW v3.1.0).\n *   부착: ACU 매니퓰레이터. 전송: CAN 2.0B 500kbps.\n *   ⚠ 본 모듈은 감사 차단(FW-EEP-3.1.0) 케이스 — 의도적 결함 포함(정적분석 실증용).\n * ============================================================ */\n#ifndef STATION_EE_PINCH_H\n#define STATION_EE_PINCH_H\n#include <stdint.h>\n\n#define CAN_ID_EE_STATE 0x18FF5201u\n#define CAN_ID_EE_FORCE 0x18FF5202u\n#define CAN_ID_EE_HB 0x18FF52F0u\n#define CAN_ID_EE_CMD 0x18EF5200u\n#define CAN_ID_EE_ACK 0x18FF52A0u\n\n#define VERB_EE_ACTUATE 0x10u\n#define VERB_EE_HOME 0x11u\n#define VERB_EE_CALIBRATE 0x12u\n\n#define ACK_RECEIVED 0x01u\n#define ACK_ACCEPTED 0x02u\n#define ACK_EXECUTED 0x03u\n\n#define EE_FORCE_MAX_MN 6000\n#define EE_MSG_MAX 16\n\ntypedef enum { EE_IDLE = 0, EE_ACTUATING = 2, EE_FAULT = 3 } ee_state_t;\n\n/* public API (api.c) */\nint ee_init(void);\nvoid ee_stop(void);\n\n/* grip control (grip_ctrl.c) */\nvoid apply_force(const uint8_t *payload, uint8_t len);\n\n/* safety interlock (safety.c) */\nint acquire_lock(void);\nint release_lock(int force);\n\n/* protocol (proto.c) */\nint parse_msg(const uint8_t *buf, uint8_t len);\n\n/* calibration (calib.c) */\nint16_t to_mm(float meters);\n\n#endif /* STATION_EE_PINCH_H */\n",
  "firmware/ee-pinching-stm32/src/api.c": "/* ============================================================\n * api.c — 적심 EE 공개 API(부트/정지).\n * ⚠ DOC-001: 공개 함수 ee_init()/ee_stop() 에 doc 주석 누락(info 등급).\n * ============================================================ */\n#include <stdint.h>\n#include \"ee.h\"\n#include \"can.h\"\n\nstatic int g_inited = 0;\n\n/* (doc 주석 없음 — DOC-001) */\nint ee_init(void) {\n  can_init(500000u);\n  acquire_lock();\n  g_inited = 1;\n  return g_inited;\n}\n\nstatic void drive_off(void) {\n  /* 드라이버 enable=0 */\n}\n\n/* (doc 주석 없음 — DOC-001) */\nvoid ee_stop(void) {\n  drive_off();\n  acquire_lock();\n}\n",
  "firmware/ee-pinching-stm32/src/calib.c": "/* ============================================================\n * calib.c — 적심 EE 캘리브레이션 단위 변환.\n * ⚠ STY-220: to_mm() 가 큰 float 를 int16_t 로 narrowing 캐스트 → integer overflow.\n * ============================================================ */\n#include <stdint.h>\n#include \"ee.h\"\n\n/* meters → mm (int16). 0.0~3.2m 가정이나 입력 검증이 없어 오버플로 가능. */\nint16_t to_mm(float meters) {\n  /* BUG(STY-220): meters*1000 이 32767 을 넘으면 int16_t 로 wrap (예: 40m→40000) */\n  int16_t mm = (int16_t)(meters * 1000.0f);\n  return mm;\n}\n\nfloat mm_to_m(int16_t mm) { return (float)mm / 1000.0f; }\n",
  "firmware/ee-pinching-stm32/src/grip_ctrl.c": "/* ============================================================\n * grip_ctrl.c — 적심 그립 힘 제어.\n * ⚠ MEM-001: apply_force() 가 외부 길이(len)를 검사 없이 고정 버퍼에 복사 →\n *   가능한 buffer overflow. (감사 정적분석 critical 검출 대상)\n * ============================================================ */\n#include <stdint.h>\n#include <string.h>\n#include \"ee.h\"\n\nstatic uint8_t g_force_profile[8]; /* 고정 8바이트 프로파일 버퍼 */\nint32_t g_applied_mn = 0;\n\nstatic int32_t decode_force(const uint8_t *p) {\n  return (int32_t)p[0] | ((int32_t)p[1] << 8);\n}\n\n/* 힘 프로파일을 수신 페이로드로 채운 뒤 드라이버에 적용한다. */\nvoid apply_force(const uint8_t *payload, uint8_t len) {\n  /* BUG(MEM-001): len 이 sizeof(g_force_profile)=8 보다 클 수 있는데 경계검사 없음 */\n  memcpy(g_force_profile, payload, len);\n\n  int32_t want = decode_force(g_force_profile);\n  if (want > EE_FORCE_MAX_MN) want = EE_FORCE_MAX_MN;\n  g_applied_mn = want;\n  /* TODO: PWM duty = want→duty */\n}\n",
  "firmware/ee-pinching-stm32/src/main.c": "/* ============================================================\n * 적심(Pinching) EE 펌웨어 메인 — STM32. 벤더: GreenEdge (MOD-EE-PINCH, FW v3.1.0).\n * ⚠ TIM-007: loop() 메인 루프에 watchdog refresh 영역 누락 → 루프 정지 시 미차단.\n * ============================================================ */\n#include <stdint.h>\n#include \"ee.h\"\n#include \"can.h\"\n\nstatic void on_command(uint32_t id, const uint8_t *d, uint8_t len) {\n  if (id != CAN_ID_EE_CMD) return;\n  parse_msg(d, len);\n}\n\nstatic void publish_hb(void) {\n  uint8_t hb[8] = {1};\n  can_send(CAN_ID_EE_HB, hb, 8);\n}\n\n/* 메인 루프 — 명령 폴링 + 주기 보고. */\nstatic void loop(void) {\n  uint32_t tick = 0;\n  for (;;) {\n    if ((tick % 1000u) == 0u) publish_hb();\n    /* BUG(TIM-007): watchdog_refresh() 호출 없음 — IWDG 미킥, 안전정지 불가 */\n    tick++;\n  }\n}\n\nint main(void) {\n  ee_init();\n  can_on_receive(on_command);\n  watchdog_start(200u); /* 시작은 하지만 loop 에서 refresh 안 함 → 결함 */\n  loop();\n  return 0;\n}\n",
  "firmware/ee-pinching-stm32/src/proto.c": "/* ============================================================\n * proto.c — 적심 EE CAN 명령 파서.\n * ⚠ MEM-003: parse_msg() 가 free() 후 해당 포인터를 다시 사용 → use-after-free.\n * ============================================================ */\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include \"ee.h\"\n\ntypedef struct { uint8_t verb; uint8_t cmd_id; uint8_t *args; uint8_t nargs; } msg_t;\n\nstatic msg_t *alloc_msg(const uint8_t *buf, uint8_t len) {\n  msg_t *m = (msg_t *)malloc(sizeof(msg_t));\n  if (!m) return 0;\n  m->verb = buf[0];\n  m->cmd_id = buf[1];\n  m->nargs = (len > 2) ? (uint8_t)(len - 2) : 0;\n  m->args = (uint8_t *)malloc(m->nargs);\n  if (m->args) memcpy(m->args, buf + 2, m->nargs);\n  return m;\n}\n\n/* 수신 프레임을 파싱해 그립 제어로 디스패치. */\nint parse_msg(const uint8_t *buf, uint8_t len) {\n  if (len < 2) return -1;\n  msg_t *m = alloc_msg(buf, len);\n  if (!m) return -1;\n\n  if (m->verb == VERB_EE_ACTUATE) {\n    apply_force(m->args, m->nargs);\n  }\n\n  free(m->args);\n  free(m);\n  /* BUG(MEM-003): m 을 free 한 뒤 다시 역참조 → use-after-free */\n  return (int)m->cmd_id;\n}\n",
  "firmware/ee-pinching-stm32/src/safety.c": "/* ============================================================\n * safety.c — 적심 EE 안전 인터록(매니퓰레이터 위치 + worker_clear).\n * ⚠ CON-014: release_lock(force) 에 interlock 검증을 우회하는 경로 존재 →\n *   safety-interlock bypass. (감사 정적분석 critical 검출 대상)\n * ============================================================ */\n#include <stdint.h>\n#include \"ee.h\"\n\nstatic volatile int g_locked = 1;       /* 1=잠금(안전) */\nstatic volatile int g_interlock_ok = 0; /* ACU 가 set: 위치확인+worker_clear */\n\nint acquire_lock(void) {\n  g_locked = 1;\n  return g_locked;\n}\n\n/* 잠금 해제 — 정상 경로는 interlock 이 충족돼야 한다. */\nint release_lock(int force) {\n  /* BUG(CON-014): force!=0 이면 interlock 검사를 건너뛰고 해제(디버그용 백도어가 남음) */\n  if (force) {\n    g_locked = 0; /* interlock 우회 — 안전 위반 */\n    return 1;\n  }\n  if (!g_interlock_ok) {\n    return 0; /* 정상: interlock 미충족 시 해제 거부 */\n  }\n  g_locked = 0;\n  return 1;\n}\n\nvoid set_interlock(int ok) { g_interlock_ok = ok ? 1 : 0; }\nint is_locked(void) { return g_locked; }\n",
  "firmware/ee-pinching-stm32/src/util.c": "/* ============================================================\n * util.c — 적심 EE 보조 함수.\n * ⚠ STY-110: 미사용 변수 + 암묵적 변환(float→int) 경고 대상.\n * ============================================================ */\n#include <stdint.h>\n#include \"ee.h\"\n\nint clampi(int v, int lo, int hi) {\n  int scratch = 0; /* BUG(STY-110): 선언 후 미사용 변수 */\n  if (v < lo) return lo;\n  if (v > hi) return hi;\n  return v;\n}\n\nuint16_t crc16(const uint8_t *d, uint8_t n) {\n  uint16_t c = 0xFFFF;\n  for (uint8_t i = 0; i < n; i++) {\n    c ^= d[i];\n    for (uint8_t b = 0; b < 8; b++) c = (c & 1) ? (c >> 1) ^ 0xA001 : (c >> 1);\n  }\n  return c;\n}\n\n/* duty(0..1) 를 PWM 카운트로. */\nint duty_to_count(float duty, int top) {\n  /* BUG(STY-110): float*int 결과를 명시 캐스트 없이 int 로 암묵 변환 */\n  int count = duty * top;\n  return count;\n}\n",
  "firmware/ee-thinning-stm32/can.h": "/* ============================================================\n * can.h — EE 보드 CAN HAL + watchdog 래퍼(골격). STM32 HAL 로 구현.\n * ============================================================ */\n#ifndef STATION_EE_CAN_H\n#define STATION_EE_CAN_H\n#include <stdint.h>\n\ntypedef void (*can_rx_cb)(uint32_t id, const uint8_t *data, uint8_t len);\n\nvoid can_init(uint32_t bitrate);\nvoid can_send(uint32_t ext_id, const uint8_t *data, uint8_t len);\nvoid can_on_receive(can_rx_cb cb);\n\n/** 독립 워치독(IWDG) — timeout_ms 내 refresh 없으면 리셋(툴 안전정지). */\nvoid watchdog_start(uint32_t timeout_ms);\nvoid watchdog_refresh(void);\n\n#endif /* STATION_EE_CAN_H */\n",
  "firmware/ee-thinning-stm32/ee.h": "/* ============================================================\n * ee.h — 적과(Thinning) 엔드이펙터 공용 정의.\n *   부착: ACU 매니퓰레이터 끝단(EE). 전송: CAN 2.0B 500kbps.\n *   벤더: GreenEdge (MOD-EE-THIN). 계약: machine.ee.* + ee.* 명령.\n * ============================================================ */\n#ifndef STATION_EE_THINNING_H\n#define STATION_EE_THINNING_H\n#include <stdint.h>\n\n/* CAN arbitration IDs (J1939 톤, EE = 0x..51..) */\n#define CAN_ID_EE_STATE 0x18FF5101u  /* telemetry: tool_state */\n#define CAN_ID_EE_FORCE 0x18FF5102u  /* telemetry: grip force (mN) */\n#define CAN_ID_EE_HB 0x18FF51F0u     /* heartbeat.ee (1Hz) */\n#define CAN_ID_EE_CMD 0x18EF5100u    /* command in: ee.* */\n#define CAN_ID_EE_ACK 0x18FF51A0u    /* 3-stage ACK */\n\n/* command verbs (payload[0]) */\n#define VERB_EE_ACTUATE 0x10u /* 적과 동작(cut) */\n#define VERB_EE_HOME 0x11u\n#define VERB_EE_CALIBRATE 0x12u\n\n/* ACK stages */\n#define ACK_RECEIVED 0x01u\n#define ACK_ACCEPTED 0x02u\n#define ACK_EXECUTED 0x03u\n\n/* tool state enum */\ntypedef enum { EE_IDLE = 0, EE_HOMING = 1, EE_ACTUATING = 2, EE_FAULT = 3 } ee_state_t;\n\n#define EE_FORCE_MAX_MN 8000 /* 안전 상한: 8N */\n\n#endif /* STATION_EE_THINNING_H */\n",
  "firmware/ee-thinning-stm32/main.c": "/* ============================================================\n * 적과(Thinning) EE 펌웨어 — STM32. 벤더: GreenEdge (MOD-EE-THIN, FW v3.1.2).\n *   역할: 매니퓰레이터 끝단 절단 툴 — 그립/절단 액추에이션, 힘 제어, 상태 보고.\n *   안전: 절단은 interlock(매니퓰레이터 위치확인 + worker_clear)이 모두 참일 때만.\n *   본 모듈은 *모범(clean)* 구현 — 경계검사·watchdog·문서화 완비(감사 통과 대상).\n * ============================================================ */\n#include <stdint.h>\n#include <string.h>\n#include \"ee.h\"\n#include \"can.h\"\n\nstatic volatile uint8_t g_interlock_ok = 0; /* ACU 가 CAN 으로 set */\nstatic ee_state_t g_state = EE_IDLE;\nstatic int32_t g_force_mn = 0;\n\n/** 힘 목표를 안전 상한으로 clamp 한 뒤 드라이버에 적용한다(경계검사 포함). */\nstatic int32_t clamp_force(int32_t want_mn) {\n  if (want_mn < 0) return 0;\n  if (want_mn > EE_FORCE_MAX_MN) return EE_FORCE_MAX_MN;\n  return want_mn;\n}\n\nstatic void send_ack(uint8_t cmd_id, uint8_t stage) {\n  uint8_t d[8] = {0};\n  d[0] = stage;\n  d[1] = cmd_id;\n  can_send(CAN_ID_EE_ACK, d, 8);\n}\n\n/** 절단 액추에이션 — interlock 검증을 통과해야만 진행(safety gate). */\nstatic void actuate(uint8_t cmd_id, int32_t force_mn) {\n  if (!g_interlock_ok) {        /* interlock 미충족 → 거부(accepted 안 함) */\n    g_state = EE_IDLE;\n    return;\n  }\n  g_force_mn = clamp_force(force_mn);\n  g_state = EE_ACTUATING;\n  send_ack(cmd_id, ACK_ACCEPTED);\n  /* TODO: 드라이버 PWM = force→duty. 완료 후: */\n  send_ack(cmd_id, ACK_EXECUTED);\n  g_state = EE_IDLE;\n}\n\n/** CAN 명령 수신 ISR → 3단계 ACK. 길이검사 후 verb 분기. */\nstatic void on_command(uint32_t id, const uint8_t *d, uint8_t len) {\n  if (id != CAN_ID_EE_CMD || len < 2) return;\n  uint8_t verb = d[0];\n  uint8_t cmd_id = d[1];\n  send_ack(cmd_id, ACK_RECEIVED);\n  switch (verb) {\n    case VERB_EE_ACTUATE: {\n      int32_t f = (len >= 4) ? ((int32_t)d[2] | ((int32_t)d[3] << 8)) : 0;\n      actuate(cmd_id, f);\n      break;\n    }\n    case VERB_EE_HOME:\n      g_state = EE_HOMING;\n      send_ack(cmd_id, ACK_ACCEPTED);\n      send_ack(cmd_id, ACK_EXECUTED);\n      g_state = EE_IDLE;\n      break;\n    case VERB_EE_CALIBRATE:\n      send_ack(cmd_id, ACK_ACCEPTED);\n      send_ack(cmd_id, ACK_EXECUTED);\n      break;\n    default:\n      break;\n  }\n}\n\n/** interlock 상태 갱신(ACU → EE) — 별도 프레임. */\nstatic void on_interlock(const uint8_t *d, uint8_t len) {\n  if (len >= 1) g_interlock_ok = d[0] ? 1u : 0u;\n}\n\nstatic void publish_state(void) {\n  uint8_t d[8] = {0};\n  d[0] = (uint8_t)g_state;\n  can_send(CAN_ID_EE_STATE, d, 8);\n  int16_t f = (int16_t)g_force_mn;\n  uint8_t fd[8] = {(uint8_t)(f & 0xFF), (uint8_t)((f >> 8) & 0xFF)};\n  can_send(CAN_ID_EE_FORCE, fd, 8);\n}\n\nint main(void) {\n  can_init(500000u);\n  can_on_receive(on_command);\n  watchdog_start(200u); /* 200ms IWDG — 루프 정지 시 툴 안전정지 */\n\n  uint32_t tick = 0;\n  for (;;) {\n    if ((tick % 100u) == 0u) publish_state(); /* 10Hz */\n    if ((tick % 1000u) == 0u) {               /* 1Hz heartbeat */\n      uint8_t hb[8] = {1};\n      can_send(CAN_ID_EE_HB, hb, 8);\n    }\n    watchdog_refresh(); /* 매 루프 watchdog kick — 정지 시 차단 */\n    tick++;\n  }\n}\n",
  "firmware/mcu-stm32/can.h": "/* ============================================================\n * can.h — 보드 CAN HAL 래퍼(골격). STM32 HAL(bxCAN/FDCAN) 또는\n *   Arduino Portenta MC CAN 라이브러리로 구현한다. 종단 ACK 없음(at_most_once).\n * ============================================================ */\n#ifndef STATION_MCU_CAN_H\n#define STATION_MCU_CAN_H\n#include <stdint.h>\n\ntypedef void (*can_rx_cb)(uint32_t id, const uint8_t *data, uint8_t len);\n\n/** 비트레이트로 CAN 주변장치 초기화(예 500000). TODO: 필터/IRQ 설정. */\nvoid can_init(uint32_t bitrate);\n\n/** 확장(29-bit) 프레임 송신. len<=8. 비차단(메일박스). */\nvoid can_send(uint32_t ext_id, const uint8_t *data, uint8_t len);\n\n/** 수신 콜백 등록 — RX FIFO 인터럽트에서 호출. */\nvoid can_on_receive(can_rx_cb cb);\n\n#endif /* STATION_MCU_CAN_H */\n",
  "firmware/mcu-stm32/main.c": "/* ============================================================\n * MCU 노드 — STM32 / Arduino Portenta Machine Control (베어메탈/HAL).\n * 역할(금지 포함): 실시간 하위제어 — motor enable·speed exec·encoder·\n *   bumper·E-stop 입력·BMS 상태읽기·safe stop·watchdog (10~1000Hz).\n *   미션/AI 판단 금지(=ACU). 출처: docs/architecture/sdv-crop-growth-rig.md §02.\n *\n * 계약(시뮬 nodes/mcu/src/index.ts 와 동일):\n *   Signal   machine.motion.speed (m/s, 20Hz) · machine.battery.voltage\n *   Command  motion.stop · motion.set_speed_limit\n *   Event    emergency_stop\n *   ACK      received → accepted → executed (3단계)\n *\n * 전송: CAN 2.0B 500kbps. 신호는 *바이너리* 프레임(JSON 아님 — 8B/frame).\n *   arbitration id 예: 0x18FF50xx (proprietary, priority 6).\n *\n * 안전: E-stop 은 본 SW 가 아니라 물리 NC 릴레이가 모터 전원을 끊는다(권한 ① 물리).\n *   여기서는 *상태 보고*만 한다(docs/architecture/sdv-rig-build-guide.md PANEL 4).\n * ============================================================ */\n#include <stdint.h>\n#include \"can.h\" /* TODO: 보드 HAL CAN 래퍼(아래 can.h 골격) */\n\n/* --- CAN arbitration IDs (J1939 톤) ----------------------- */\n#define CAN_ID_MOTION_SPEED 0x18FF5001u /* telemetry: 속도 */\n#define CAN_ID_BATTERY 0x18FF5002u      /* telemetry: BMS 전압 */\n#define CAN_ID_EMERGENCY 0x18FFE000u    /* event: e-stop (최우선) */\n#define CAN_ID_CMD_MOTION 0x18EF5000u   /* command in: motion.* */\n\n/* --- command verb 코드(8B 페이로드 첫 바이트) ------------- */\n#define VERB_MOTION_STOP 0x01u\n#define VERB_SET_SPEED_LIMIT 0x02u\n\n/* --- ACK stage 코드 --------------------------------------- */\n#define ACK_RECEIVED 0x01u\n#define ACK_ACCEPTED 0x02u\n#define ACK_EXECUTED 0x03u\n#define CAN_ID_ACK 0x18FF50A0u\n\nstatic volatile uint8_t g_estop_latched = 0; /* E-stop GPIO 인터럽트가 set */\nstatic float g_speed_mps = 1.2f;             /* 현재 구동 속도 */\nstatic float g_speed_limit = 1.5f;\n\n/* 속도(m/s)를 mm/s int16 로 패킹해 8B 프레임으로 — JSON 금지(레퍼런스 교훈). */\nstatic void publish_speed(void) {\n  uint8_t d[8] = {0};\n  int16_t mmps = (int16_t)(g_speed_mps * 1000.0f);\n  d[0] = (uint8_t)(mmps & 0xFF);\n  d[1] = (uint8_t)((mmps >> 8) & 0xFF);\n  can_send(CAN_ID_MOTION_SPEED, d, 8); /* TODO: 실 BMS/엔코더 값 채움 */\n}\n\nstatic void send_ack(uint32_t cmd_id, uint8_t stage) {\n  uint8_t d[8] = {0};\n  d[0] = stage;\n  d[1] = (uint8_t)(cmd_id & 0xFF);\n  can_send(CAN_ID_ACK, d, 8);\n}\n\n/* 명령 수신 ISR → 3단계 ACK. accepted 는 robot-side 안전조건 통과 후. */\nstatic void on_command(uint32_t id, const uint8_t *d, uint8_t len) {\n  if (id != CAN_ID_CMD_MOTION || len < 2) return;\n  uint8_t verb = d[0];\n  uint32_t cmd_id = d[1];\n  send_ack(cmd_id, ACK_RECEIVED);\n  if (g_estop_latched) return; /* 안전 미충족 → accepted 안 함 */\n  switch (verb) {\n    case VERB_MOTION_STOP:\n      g_speed_mps = 0.0f; /* TODO: 모터 드라이버 enable=0 */\n      send_ack(cmd_id, ACK_ACCEPTED);\n      send_ack(cmd_id, ACK_EXECUTED);\n      break;\n    case VERB_SET_SPEED_LIMIT:\n      g_speed_limit = (float)d[1] / 10.0f;\n      send_ack(cmd_id, ACK_ACCEPTED);\n      send_ack(cmd_id, ACK_EXECUTED);\n      break;\n    default:\n      break; /* 미지원 verb */\n  }\n}\n\n/* E-stop GPIO 인터럽트 — 물리 회로가 전원을 끊은 뒤, SW 는 보고만. */\nvoid EXTI_EStop_IRQHandler(void) {\n  g_estop_latched = 1;\n  uint8_t d[8] = {1};\n  can_send(CAN_ID_EMERGENCY, d, 8); /* event: emergency_stop */\n}\n\nint main(void) {\n  /* TODO: HAL_Init() · SystemClock_Config() · GPIO/CAN/TIM init */\n  can_init(500000u); /* 500 kbps */\n  can_on_receive(on_command);\n  /* TODO: watchdog(IWDG) 시작 — 루프가 멈추면 모터 차단 */\n\n  uint32_t tick = 0;\n  for (;;) {\n    /* 20Hz 속도 발행 */\n    if ((tick % 50u) == 0u) publish_speed();\n    /* 1Hz BMS 전압(예시) */\n    if ((tick % 1000u) == 0u) {\n      uint8_t d[8] = {0};\n      uint16_t mv = 24000; /* TODO: 실 BMS ADC */\n      d[0] = (uint8_t)(mv & 0xFF);\n      d[1] = (uint8_t)((mv >> 8) & 0xFF);\n      can_send(CAN_ID_BATTERY, d, 8);\n    }\n    /* TODO: IWDG_Refresh() · 1ms delay(타이머 기반) */\n    tick++;\n  }\n}\n",
  "firmware/vpu-ros2/vpu_node.py": "#!/usr/bin/env python3\n# ============================================================\n# VPU 노드 — Jetson Orin Nano · ROS2(rclpy) · 생육분석.\n# 역할(금지 포함): RGB/NIR 수집 · 생육분석 추론(초장·LAI·NDVI·병해 의심) ·\n#   image quality · scan result event. 모터/안전 직접제어 금지(=MCU/ACU 경유).\n#   출처: docs/architecture/sdv-crop-growth-rig.md §02.\n#\n# 계약(시뮬 nodes/vpu/src/index.ts 와 동일):\n#   Signal   crop.growth.lai · crop.growth.ndvi · vision.fps  (rt/crop/growth)\n#   Command  vision.capture · scan · calibrate                (rt/vision/capture)\n#   Event    disease.suspected                                (rt/disease/suspected)\n#   QoS      텔레메트리 RELIABLE(분석 결과는 손실 불가)\n#\n# 빌드 가능한 완성품 아님 — TODO 가 실구현(카메라·CUDA 추론) 지점.\n# ============================================================\nimport rclpy\nfrom rclpy.node import Node\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, DurabilityPolicy\n\n# TODO: 실제로는 station_msgs/Signal 커스텀 메시지 사용. 골격은 std_msgs 로 형태만.\nfrom std_msgs.msg import String  # noqa: F401  (placeholder for Signal msg)\n\n\nRELIABLE = QoSProfile(\n    depth=10,\n    reliability=ReliabilityPolicy.RELIABLE,\n    durability=DurabilityPolicy.VOLATILE,\n)\n\n\nclass VpuNode(Node):\n    def __init__(self) -> None:\n        super().__init__(\"vpu_node\")\n        # 텔레메트리 발행(rt/crop/growth) — RELIABLE.\n        self.pub_growth = self.create_publisher(String, \"crop/growth\", RELIABLE)\n        self.pub_disease = self.create_publisher(String, \"disease/suspected\", RELIABLE)\n        # 명령 구독(rt/vision/capture).\n        self.create_subscription(String, \"vision/capture\", self.on_command, RELIABLE)\n        # 5Hz 생육분석 발행.\n        self.create_timer(0.2, self.tick)\n        self.get_logger().info(\"VPU up — Jetson Orin · ROS2 RELIABLE\")\n\n    def tick(self) -> None:\n        # TODO: 카메라 프레임 캡처 → CUDA 생육분석 추론 → 실 값.\n        ndvi, lai, fps = 0.81, 3.1, 12.0\n        self.pub_growth.publish(String(data=f\"crop.growth.ndvi={ndvi};lai={lai};vision.fps={fps}\"))\n        # 병해 의심 시 이벤트(예시 조건).\n        if ndvi < 0.2:\n            self.pub_disease.publish(String(data=\"disease.suspected\"))\n\n    def on_command(self, msg: \"String\") -> None:\n        # TODO: vision.capture/scan/calibrate 처리 + 3단계 ACK(rt/.../ack).\n        self.get_logger().info(f\"command: {msg.data}\")\n\n\ndef main() -> None:\n    rclpy.init()\n    node = VpuNode()\n    try:\n        rclpy.spin(node)\n    finally:\n        node.destroy_node()\n        rclpy.shutdown()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "ros2/acu_autonomy/src/acu_node.cpp": "// ============================================================\n// ACU 자율 노드 — 메타파머스. ROS2/DDS (IF-P-ACU).\n//   퍼블리시: machine.autonomy.{state,mode}(RELIABLE), machine.navigation.deviation(BEST_EFFORT)\n//   서브스크라이브: autonomy.{mission.start,pause,slow_down} (RELIABLE)\n//   ⚠ 본 모듈은 감사 재검증(TS-ACU) 대상 — C++ 정적분석 경고 시드 포함:\n//     · QOS-002: 안전 상태 토픽을 BEST_EFFORT 로 다운그레이드(IF-P 는 RELIABLE 요구)\n//     · RES-001: raw new 자원 누수(소멸 경로 없음)\n// ============================================================\n#include <chrono>\n#include <cmath>\n#include <memory>\n#include <string>\n\n#include \"rclcpp/rclcpp.hpp\"\n#include \"std_msgs/msg/float64.hpp\"\n#include \"std_msgs/msg/string.hpp\"\n\nusing namespace std::chrono_literals;\n\nenum class Mission { kIdle = 0, kRunning = 1, kPaused = 2 };\n\nstruct MissionLog {  // 누적 미션 로그(예시 자원)\n  std::string buf;\n};\n\nclass AcuNode : public rclcpp::Node {\n public:\n  AcuNode() : Node(\"acu_autonomy\") {\n    auto reliable = rclcpp::QoS(rclcpp::KeepLast(10)).reliable();\n    auto best_effort = rclcpp::QoS(rclcpp::KeepLast(10)).best_effort();\n\n    // BUG(QOS-002): autonomy.state 는 IF-P-ACU 에서 RELIABLE 이어야 하나 BEST_EFFORT 로 생성.\n    state_pub_ = create_publisher<std_msgs::msg::String>(\"rt/autonomy/state\", best_effort);\n    mode_pub_ = create_publisher<std_msgs::msg::Float64>(\"rt/autonomy/mode\", reliable);\n    dev_pub_ = create_publisher<std_msgs::msg::Float64>(\"rt/navigation/deviation\", best_effort);\n    hb_pub_ = create_publisher<std_msgs::msg::String>(\"rt/heartbeat/acu\", reliable);\n\n    cmd_sub_ = create_subscription<std_msgs::msg::String>(\n        \"rt/mission/cmd\", reliable,\n        [this](const std_msgs::msg::String::SharedPtr m) { on_cmd(m->data); });\n\n    // BUG(RES-001): raw new — 소멸자/delete 없음(누수). unique_ptr 로 했어야.\n    log_ = new MissionLog();\n\n    timer_ = create_wall_timer(50ms, [this]() { tick(); });\n    hb_timer_ = create_wall_timer(1s, [this]() { heartbeat(); });\n  }\n\n private:\n  void on_cmd(const std::string & verb) {\n    if (verb == \"autonomy.mission.start\") {\n      state_ = Mission::kRunning;\n      speed_factor_ = 1.0;\n    } else if (verb == \"autonomy.pause\") {\n      state_ = Mission::kPaused;\n    } else if (verb == \"autonomy.slow_down\") {\n      speed_factor_ = std::max(0.25, speed_factor_ * 0.5);\n    }\n    log_->buf += verb + \";\";\n  }\n\n  void tick() {\n    t_ += 0.05;\n    double dev = (state_ == Mission::kRunning) ? 20.0 * speed_factor_ * std::sin(t_) : 0.0;\n\n    std_msgs::msg::String s;\n    s.data = state_str();\n    state_pub_->publish(s);\n\n    std_msgs::msg::Float64 mode;\n    mode.data = (speed_factor_ < 1.0) ? 2.0 : 1.0;\n    mode_pub_->publish(mode);\n\n    std_msgs::msg::Float64 d;\n    d.data = dev;\n    dev_pub_->publish(d);\n  }\n\n  void heartbeat() {\n    std_msgs::msg::String hb;\n    hb.data = \"acu\";\n    hb_pub_->publish(hb);\n  }\n\n  const char * state_str() const {\n    switch (state_) {\n      case Mission::kRunning: return \"running\";\n      case Mission::kPaused: return \"paused\";\n      default: return \"idle\";\n    }\n  }\n\n  rclcpp::Publisher<std_msgs::msg::String>::SharedPtr state_pub_;\n  rclcpp::Publisher<std_msgs::msg::Float64>::SharedPtr mode_pub_;\n  rclcpp::Publisher<std_msgs::msg::Float64>::SharedPtr dev_pub_;\n  rclcpp::Publisher<std_msgs::msg::String>::SharedPtr hb_pub_;\n  rclcpp::Subscription<std_msgs::msg::String>::SharedPtr cmd_sub_;\n  rclcpp::TimerBase::SharedPtr timer_;\n  rclcpp::TimerBase::SharedPtr hb_timer_;\n\n  Mission state_ = Mission::kIdle;\n  double t_ = 0.0, speed_factor_ = 1.0;\n  MissionLog * log_ = nullptr;\n};\n\nint main(int argc, char ** argv) {\n  rclcpp::init(argc, argv);\n  rclcpp::spin(std::make_shared<AcuNode>());\n  rclcpp::shutdown();\n  return 0;\n}\n",
  "ros2/lpu_localization/src/lpu_node.cpp": "// ============================================================\n// LPU 측위 노드 — 대동로보틱스. ROS2/DDS (IF-P-LPU).\n//   퍼블리시: machine.localization.{pose,map_match,confidence} (BEST_EFFORT/RELIABLE)\n//   서브스크라이브: localization.relocalize (RELIABLE)\n//   결정적 측위 시뮬: 신뢰도 회복 + waypoint 추종(사인 경로). 본 모듈은 clean 구현.\n// ============================================================\n#include <chrono>\n#include <cmath>\n#include <memory>\n#include <string>\n\n#include \"rclcpp/rclcpp.hpp\"\n#include \"std_msgs/msg/float64.hpp\"\n#include \"std_msgs/msg/string.hpp\"\n#include \"geometry_msgs/msg/pose2_d.hpp\"\n\nusing namespace std::chrono_literals;\n\nnamespace {\nconstexpr double kConfidenceFloor = 0.35;\nconstexpr double kConfidenceTarget = 0.97;\n}  // namespace\n\nclass LpuNode : public rclcpp::Node {\n public:\n  LpuNode() : Node(\"lpu_localization\") {\n    // 안전/신뢰성 토픽은 RELIABLE, 고빈도 pose 는 BEST_EFFORT (IF-P-LPU QoS 정합).\n    auto best_effort = rclcpp::QoS(rclcpp::KeepLast(10)).best_effort();\n    auto reliable = rclcpp::QoS(rclcpp::KeepLast(10)).reliable();\n\n    pose_pub_ = create_publisher<geometry_msgs::msg::Pose2D>(\"rt/localization/pose\", best_effort);\n    match_pub_ = create_publisher<std_msgs::msg::Float64>(\"rt/localization/map_match\", best_effort);\n    conf_pub_ = create_publisher<std_msgs::msg::Float64>(\"rt/localization/confidence\", reliable);\n    hb_pub_ = create_publisher<std_msgs::msg::String>(\"rt/heartbeat/lpu\", reliable);\n\n    relocalize_sub_ = create_subscription<std_msgs::msg::String>(\n        \"rt/localization/relocalize\", reliable,\n        [this](const std_msgs::msg::String::SharedPtr msg) { on_relocalize(msg->data); });\n\n    timer_ = create_wall_timer(50ms, [this]() { tick(); });   // 20Hz\n    hb_timer_ = create_wall_timer(1s, [this]() { heartbeat(); });\n  }\n\n private:\n  void on_relocalize(const std::string & reason) {\n    RCLCPP_INFO(get_logger(), \"relocalize requested: %s\", reason.c_str());\n    confidence_ = kConfidenceFloor;  // 재측위 → 신뢰도 리셋 후 회복\n  }\n\n  void tick() {\n    t_ += 0.05;\n    // waypoint 추종: 사인 경로\n    pose_x_ = t_ * 0.6;\n    pose_y_ = 0.5 * std::sin(t_ * 0.4);\n    theta_ = std::atan2(0.5 * 0.4 * std::cos(t_ * 0.4), 0.6);\n    // 신뢰도 점근 회복\n    confidence_ += (kConfidenceTarget - confidence_) * 0.05;\n    map_match_ = std::min(1.0, confidence_ + 0.01);\n\n    geometry_msgs::msg::Pose2D p;\n    p.x = pose_x_;\n    p.y = pose_y_;\n    p.theta = theta_;\n    pose_pub_->publish(p);\n\n    std_msgs::msg::Float64 m;\n    m.data = map_match_;\n    match_pub_->publish(m);\n\n    std_msgs::msg::Float64 c;\n    c.data = confidence_;\n    conf_pub_->publish(c);\n  }\n\n  void heartbeat() {\n    std_msgs::msg::String hb;\n    hb.data = \"lpu\";\n    hb_pub_->publish(hb);\n  }\n\n  rclcpp::Publisher<geometry_msgs::msg::Pose2D>::SharedPtr pose_pub_;\n  rclcpp::Publisher<std_msgs::msg::Float64>::SharedPtr match_pub_;\n  rclcpp::Publisher<std_msgs::msg::Float64>::SharedPtr conf_pub_;\n  rclcpp::Publisher<std_msgs::msg::String>::SharedPtr hb_pub_;\n  rclcpp::Subscription<std_msgs::msg::String>::SharedPtr relocalize_sub_;\n  rclcpp::TimerBase::SharedPtr timer_;\n  rclcpp::TimerBase::SharedPtr hb_timer_;\n\n  double t_ = 0.0, pose_x_ = 0.0, pose_y_ = 0.0, theta_ = 0.0;\n  double confidence_ = kConfidenceFloor, map_match_ = kConfidenceFloor;\n};\n\nint main(int argc, char ** argv) {\n  rclcpp::init(argc, argv);\n  rclcpp::spin(std::make_shared<LpuNode>());\n  rclcpp::shutdown();\n  return 0;\n}\n",
  "telemetry/telemetry_gw/telemetry_gw/__init__.py": "\"\"\"STATION Telemetry Gateway — 비아 (IF-P-TEL, MQTT).\"\"\"\n__version__ = \"1.0.0\"\n",
  "telemetry/telemetry_gw/telemetry_gw/gateway.py": "\"\"\"Telemetry 게이트웨이 — env.greenhouse.* 신호를 MQTT 로 업링크 (IF-P-TEL).\n\n토픽: station/{site}/{robot}/tlm/env/* (QoS1, retain). 명령: telemetry.uplink.flush.\n오프라인 시 버퍼링 후 재연결에 flush. 본 모듈은 clean 구현(감사 통과 대상).\n\"\"\"\nfrom __future__ import annotations\n\nfrom collections import deque\nfrom dataclasses import dataclass\n\n# wire.telemetry.mqtt.json 과 정합\nTOPIC_TMPL = {\n    \"env.greenhouse.temperature\": \"station/{site}/{robot}/tlm/env/temperature\",\n    \"env.greenhouse.humidity\": \"station/{site}/{robot}/tlm/env/humidity\",\n    \"env.greenhouse.co2\": \"station/{site}/{robot}/tlm/env/co2\",\n    \"machine.telemetry.cloud_connected\": \"station/{site}/{robot}/tlm/cloud_connected\",\n}\nQOS1 = 1\n\n\n@dataclass\nclass Sample:\n    channel: str\n    value: float\n    ts: str\n\n\nclass TelemetryGateway:\n    def __init__(self, site: str, robot: str, max_buffer: int = 5000) -> None:\n        self.site = site\n        self.robot = robot\n        self.connected = False\n        self.buffer: deque[Sample] = deque(maxlen=max_buffer)\n\n    def topic_for(self, channel: str) -> str | None:\n        tmpl = TOPIC_TMPL.get(channel)\n        if tmpl is None:\n            return None\n        return tmpl.format(site=self.site, robot=self.robot)\n\n    def publish(self, s: Sample) -> bool:\n        \"\"\"연결 시 즉시 발행, 아니면 버퍼링(QoS1·retain 은 보드 client).\"\"\"\n        topic = self.topic_for(s.channel)\n        if topic is None:\n            return False  # 미선언 채널 — 업링크 거부(IF-P 위반 방지)\n        if not self.connected:\n            self.buffer.append(s)\n            return False\n        self._send(topic, s.value)\n        return True\n\n    def on_reconnect(self) -> int:\n        \"\"\"재연결 시 버퍼 flush — 전송 건수 반환.\"\"\"\n        self.connected = True\n        n = 0\n        while self.buffer:\n            s = self.buffer.popleft()\n            topic = self.topic_for(s.channel)\n            if topic is not None:\n                self._send(topic, s.value)\n                n += 1\n        return n\n\n    def flush(self) -> int:\n        \"\"\"telemetry.uplink.flush 명령 핸들러.\"\"\"\n        return self.on_reconnect() if self.connected else 0\n\n    def _send(self, topic: str, value: float) -> None:\n        # 보드: client.publish(topic, payload, qos=QOS1, retain=True)\n        _ = (topic, value, QOS1)\n\n\ndef main() -> None:\n    gw = TelemetryGateway(site=\"SITE-GIMJE-01\", robot=\"RBT-THIN-0001\")\n    gw.publish(Sample(\"env.greenhouse.temperature\", 24.6, \"2026-06-07T09:00:00Z\"))\n    gw.on_reconnect()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "vision/vpu_vision/vpu/__init__.py": "\"\"\"STATION VPU 비전 패키지 — 메타파머스 (IF-P-VPU, ROS2).\"\"\"\n__version__ = \"2.4.2\"\n",
  "vision/vpu_vision/vpu/node.py": "\"\"\"VPU ROS2 노드 — 비전 신호/명령 브리지 (IF-P-VPU).\n\n퍼블리시: machine.vision.{fps,framedrop,worker_detected} + crop.growth.* + heartbeat.vpu\n서브스크라이브: vision.capture.{start,stop} · vision.calibrate\n이벤트: disease.suspected\n\"\"\"\nfrom __future__ import annotations\n\nimport time\n\nfrom .vision import GrowthEstimator, detect_worker, estimate_fps, framedrop_ratio\n\n# IF-P-VPU 토픽 매핑(wire.vpu.ros2.json 과 정합)\nTOPICS = {\n    \"fps\": \"rt/vision/fps\",\n    \"framedrop\": \"rt/vision/framedrop\",\n    \"worker_detected\": \"rt/vision/worker_detected\",\n    \"capture\": \"rt/vision/capture\",\n    \"calibrate\": \"rt/vision/calibrate\",\n    \"disease\": \"rt/vision/disease\",\n    \"heartbeat\": \"rt/heartbeat/vpu\",\n}\n\n\nclass VpuNode:\n    \"\"\"rclpy.Node 래퍼(보드). 여기서는 결정적 루프로 거동을 재현.\"\"\"\n\n    def __init__(self) -> None:\n        self.scanning = False\n        self.frame = 0\n        self.growth = GrowthEstimator()\n\n    def on_command(self, verb: str) -> None:\n        if verb == \"vision.capture.start\":\n            self.scanning = True\n        elif verb == \"vision.capture.stop\":\n            self.scanning = False\n        elif verb == \"vision.calibrate\":\n            self.growth = GrowthEstimator()\n\n    def tick(self) -> dict[str, float | bool]:\n        \"\"\"30Hz 가정 1틱 — 신호 dict 반환(퍼블리시는 보드 rclpy).\"\"\"\n        self.frame += 1\n        out: dict[str, float | bool] = {\n            \"machine.vision.fps\": estimate_fps([33.0]),\n            \"machine.vision.framedrop\": framedrop_ratio(self.frame, self.frame + 1),\n            \"machine.vision.worker_detected\": detect_worker(self.frame),\n        }\n        if self.scanning:\n            out.update(self.growth.step())\n        return out\n\n\ndef main() -> None:\n    node = VpuNode()\n    node.on_command(\"vision.capture.start\")\n    for _ in range(5):\n        _ = node.tick()\n        time.sleep(0.01)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "vision/vpu_vision/vpu/vision.py": "\"\"\"비전 파이프라인 — RGB/NIR 프레임에서 fps·framedrop·worker_detect·생육지표 산출.\n\n결정적 시뮬(보드 부재 시): 프레임 카운트 기반 생육 곡선 + 주기적 worker 감지.\n실 보드에서는 OpenCV/NN 으로 대체. 본 모듈은 mostly-clean 이나\nPython 정적분석 경고를 일부 시드(PY-BARE-EXCEPT, PY-MUTABLE-DEFAULT).\n\"\"\"\nfrom __future__ import annotations\n\nimport math\n\n\nclass GrowthEstimator:\n    \"\"\"프레임 진행에 따른 생육지표(plant_height·lai·ndvi) 추정기.\"\"\"\n\n    def __init__(self, total_frames: int = 120) -> None:\n        self.total = total_frames\n        self.frame = 0\n\n    def step(self) -> dict[str, float]:\n        self.frame = min(self.frame + 1, self.total)\n        p = self.frame / self.total\n        return {\n            \"crop.growth.plant_height\": round(0.2 + 1.6 * p, 3),      # m\n            \"crop.growth.lai\": round(0.5 + 3.5 * p, 3),               # leaf area index\n            \"crop.growth.ndvi\": round(0.35 + 0.5 * math.sin(p * 1.2), 3),\n        }\n\n\ndef estimate_fps(frame_times_ms, history=[]):  # noqa: B006\n    \"\"\"최근 프레임 간격으로 fps 추정.\n\n    BUG(PY-MUTABLE-DEFAULT): history=[] 가변 기본 인자 — 호출 간 상태 누수.\n    \"\"\"\n    history.extend(frame_times_ms)\n    if not history:\n        return 0.0\n    avg_ms = sum(history) / len(history)\n    return round(1000.0 / avg_ms, 1) if avg_ms > 0 else 0.0\n\n\ndef detect_worker(frame_index: int) -> bool:\n    \"\"\"작업자 감지(안전정책 입력). 시뮬: 주기적으로 True.\"\"\"\n    try:\n        return (frame_index % 200) in (10, 11, 12)\n    except Exception:  # noqa: E722  BUG(PY-BARE-EXCEPT): 광범위 except 로 오류 은폐\n        return False\n\n\ndef framedrop_ratio(produced: int, expected: int) -> float:\n    if expected <= 0:\n        return 0.0\n    return round(max(0.0, (expected - produced) / expected), 3)\n",
};
